const profil = $('Extraire texte profil').first().json.data || '';
const guide = $('Extraire texte guide').first().json.data || '';
const refMissive = $('Extraire texte reference missive').first().json.data || '';
const promptTemplate = $('Extraire texte prompt missive').first().json.data || '';

const contenusRaw = $('Lire contenus publies').all().map(i => i.json);
const propositionsRaw = $('Lire propositions mois').all().map(i => i.json);

const now = new Date();
const moisCourant = now.getMonth();
const anneeCourante = now.getFullYear();

function estMoisCourant(dateStr) {
  if (!dateStr) return false;
  const d = new Date(dateStr);
  return d.getMonth() === moisCourant && d.getFullYear() === anneeCourante;
}

// Filtrer contenus PUBLIE du mois courant uniquement
const contenus = contenusRaw.filter(c => {
  const statut = (c.Statut || c.statut || '').trim().toUpperCase();
  const isPublie = statut === 'PUBLI\u00c9' || statut === 'PUBLIE';
  const dateStr = c['Date publication'] || c.Date || c.date || '';
  return isPublie && estMoisCourant(dateStr);
});

// Collecter les row_number des lignes utilisees (pour formatage vert)
const usedBrouillonRows = contenus.map(c => c.row_number).filter(Boolean);

const propositions = propositionsRaw.filter(p => estMoisCourant(p.Date || p.date));

const moisAnnee = now.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });

let prompt = promptTemplate;
prompt = prompt.replace('\u007b\u007bPROFIL_BUSINESS\u007d\u007d', profil);
prompt = prompt.replace('\u007b\u007bGUIDE_EDITORIAL\u007d\u007d', guide);
prompt = prompt.replace('\u007b\u007bREFERENCE_MISSIVE\u007d\u007d', refMissive);
prompt = prompt.replace('\u007b\u007bMOIS_ANNEE\u007d\u007d', moisAnnee);
prompt = prompt.replace('\u007b\u007bCONTENUS_PUBLIES\u007d\u007d', JSON.stringify(contenus, null, 2));
prompt = prompt.replace('\u007b\u007bPROPOSITIONS_MOIS\u007d\u007d', JSON.stringify(propositions, null, 2));
prompt = prompt.replace('\u007b\u007bSOURCES_PERPLEXITY_MOIS\u007d\u007d', propositions.map(p => p.Sources || p.sources || '').filter(Boolean).join('\n'));

return [{ json: { prompt, moisAnnee, usedBrouillonRows, contenusCount: contenus.length, propositionsCount: propositions.length } }];

const response = $input.first().json;
const raw = response.candidates?.[0]?.content?.parts?.[0]?.text;
let missive;

if (typeof raw === 'object' && raw !== null) {
  missive = raw;
} else if (typeof raw === 'string') {
  try {
    missive = JSON.parse(raw);
  } catch(e) {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      try { missive = JSON.parse(match[0]); } catch(e2) { missive = null; }
    }
  }
}

if (!missive) {
  missive = { titre: 'La Missive du Prof', contenu: raw || '' };
}

const meta = $('Assembler prompt Missive').first().json;

return [{
  json: {
    titre: missive.titre || 'La Missive du Prof - ' + meta.moisAnnee,
    contenu: missive.contenu || '',
    hook: missive.hook || '',
    cta: missive.cta || '',
    notes: missive.notes_internes || '',
    moisAnnee: meta.moisAnnee
  }
}];

const m = $('Parser Missive').first().json;
const docId = $input.first().json.id;

function cleanMd(text) {
  if (!text) return '';
  return text
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/\*(.+?)\*/g, '$1');
}

const docSections = [];

// Titre
docSections.push({ text: m.titre + '\n', style: 'TITLE' });

// Sommaire
if (m.hook) {
  docSections.push({ text: '\nDans cette missive\n', style: 'HEADING_2' });
  docSections.push({ text: cleanMd(m.hook) + '\n', style: 'NORMAL_TEXT' });
}

// Contenu principal
const lines = (m.contenu || '').split('\n');
let paragraph = '';

for (const line of lines) {
  const headingMatch = line.match(/^(#{1,3})\s+(.+)$/);
  if (headingMatch) {
    if (paragraph.trim()) {
      docSections.push({ text: paragraph, style: 'NORMAL_TEXT' });
      paragraph = '';
    }
    const level = headingMatch[1].length;
    const styles = { 1: 'HEADING_1', 2: 'HEADING_2', 3: 'HEADING_3' };
    docSections.push({ text: '\n' + cleanMd(headingMatch[2]) + '\n', style: styles[level] });
  } else if (line.trim() === '---') {
    if (paragraph.trim()) {
      docSections.push({ text: paragraph, style: 'NORMAL_TEXT' });
      paragraph = '';
    }
  } else {
    paragraph += cleanMd(line) + '\n';
  }
}
if (paragraph.trim()) {
  docSections.push({ text: paragraph, style: 'NORMAL_TEXT' });
}

// CTA
if (m.cta) {
  docSections.push({ text: '\n' + cleanMd(m.cta) + '\n', style: 'NORMAL_TEXT' });
}

// Signature
docSections.push({ text: '\nLe Prof\n', style: 'NORMAL_TEXT' });

// Notes internes
if (m.notes) {
  docSections.push({ text: '\nNOTES INTERNES (a supprimer avant envoi)\n', style: 'HEADING_3' });
  docSections.push({ text: cleanMd(m.notes) + '\n', style: 'NORMAL_TEXT' });
}

// Construire les requetes Google Docs API
const requests = [];
const fullText = docSections.map(s => s.text).join('');

requests.push({
  insertText: {
    location: { index: 1 },
    text: fullText
  }
});

let idx = 1;
for (const section of docSections) {
  if (section.style !== 'NORMAL_TEXT') {
    requests.push({
      updateParagraphStyle: {
        range: {
          startIndex: idx,
          endIndex: idx + section.text.length
        },
        paragraphStyle: {
          namedStyleType: section.style
        },
        fields: 'namedStyleType'
      }
    });
  }
  idx += section.text.length;
}

return [{ json: { docId, body: { requests } } }];

// Recuperer les row_number des contenus PUBLIE utilises
const rows = $('Assembler prompt Missive').first().json.usedBrouillonRows || [];

if (rows.length === 0) {
  return [{ json: { skip: true, message: 'Aucune ligne a formater' } }];
}

// Preparer les requetes repeatCell pour chaque ligne
const requests = rows.map(rowNum => ({
  repeatCell: {
    range: {
      sheetId: 1111947149,
      startRowIndex: rowNum - 1,
      endRowIndex: rowNum,
      startColumnIndex: 0,
      endColumnIndex: 11
    },
    cell: {
      userEnteredFormat: {
        backgroundColor: {
          red: 0.851,
          green: 0.918,
          blue: 0.827
        }
      }
    },
    fields: 'userEnteredFormat.backgroundColor'
  }
}));

return [{ json: { skip: false, body: { requests } } }];
